
<!-- Full-text site search (Ctrl/⌘ K), using data generated by ../search.ts during the build
     NOTE The results list is rendered with innerHTML rather than Vue as it re-renders per key -->


<template lang='pug'>

div.nav-search
    button.open(type='button' aria-label="Search the site" @click='open' @pointerenter='warm'
            @focusin='warm' @touchstart.passive='warm')
        svg(viewBox='0 0 24 24' aria-hidden='true' fill='none' stroke='currentColor' stroke-width='2'
                stroke-linecap='round')
            circle(cx='11' cy='11' r='7')
            path(d='m20 20-3.5-3.5')
        span.label Search
        kbd.keys {{ mac ? '⌘' : 'Ctrl' }} K

//- Not modal (with showModal) as making the rest of a long page inert takes 100ms+ on phones
//- Only in the browser, as teleported out of the nav bar so nothing it's within can clip it
Teleport(v-if='mounted' to='body')
    div.backdrop(v-show='is_open' @click='close' @wheel.prevent @touchmove.prevent)
    dialog.palette(ref='dialog' aria-modal='true' aria-label="Search the site" @close='on_close'
            @keydown='on_dialog_key')
        div.head
            input(ref='input' type='text' role='combobox' aria-expanded='true' aria-controls='palette-list'
                aria-autocomplete='list' aria-label="Search the site"
                placeholder="Search articles, podcasts, videos…" autocomplete='off' spellcheck='false'
                enterkeyhint='go' @input='on_input' @keydown='on_input_key')
            button.close(type='button' aria-label="Close" @click='close') Esc
        //- NOTE No italics, as loading the italic font would lay out the whole page again
        div.scope(role='group' aria-label="Also search")
            span Also search
            label
                input(:checked='book_on' type='checkbox' @change='on_scope')
                |  The book “God’s Word Is Not Bound”
        ul#palette-list(ref='list' role='listbox' aria-label="Results" @click='on_click'
            @mousemove='on_move' @scroll.passive='on_scroll')

</template>


<script lang='ts' setup>

import {ref, onMounted, onBeforeUnmount, nextTick} from 'vue'
import {useRouter} from 'vitepress'

import {type Doc, type Result, words, esc, mark, search, narrows, target, line, pages_docs, add_text,
    book_docs} from './search_core'


// Set in config.ts, the same for every page of a build, so search files can be cached forever
declare const __SEARCH_VERSION__:string

const router = useRouter()
const dialog = ref<HTMLDialogElement>()
const input = ref<HTMLInputElement>()
const list = ref<HTMLUListElement>()
const mounted = ref(false)
const is_open = ref(false)
const book_on = ref(true)  // Whether to also search the book
const mac = ref(false)

// The list shown before typing (built in so it shows instantly, even before data loads)
const menu:Doc[] = [
    ["Home", '/', "Ministry should be supported, not sold"],
    ["Articles", '/learn', "Our position, objections, conversations and resources"],
    ["Videos", '/videos/documentary', "Informative videos, reactions and humor"],
    ["Podcast", '/podcast', "All episodes of the Selling Jesus podcast"],
    ["Graphics", '/graphics', "Memes and infographics to share"],
    ["Books", '/book', "Free books, in print, ebook and audio"],
    ["Take Action", '/act', "Ways to help end the Jesus trade"],
    ["About", '/about', "Who we are, our beliefs and how to contact us"],
].map(([title, href, desc]) => ({title, href, desc, section: "Pages", source: 'pages', t: ' ', m: ' ',
    x: ' ', raw: '', boost: 0}))


// LOADING

const json = (name:string, init?:RequestInit) =>
    fetch(`/_search/${name}.json?v=${__SEARCH_VERSION__}`, init)
        .then(r => r.ok ? r.json() : Promise.reject(new Error(name)))

// NOTE Pages' text is separate from their titles etc. so those can be searched sooner
const sources:Record<string, (init?:RequestInit) => Promise<unknown>> = {
    pages: init => json('pages', init).then(pages_docs),
    text: init => json('text', init),
    book: init => json('book', init).then(book_docs),
}

const loaded:Record<string, unknown> = {}
const loading:Record<string, Promise<unknown>> = {}
let failed = new Set<string>()  // Not retried until next opened (e.g. if offline)
let with_text = false
let adding_text:Promise<void>|undefined

const enabled = () => ['pages', 'text', ...(book_on.value ? ['book'] : [])]
const docs_of = (name:string) => name === 'text' ? [] : loaded[name] as Doc[]

// Store loaded data, resolving once it's ready to search
function loaded_data(name:string, data:unknown):Promise<void>{
    loaded[name] ??= data
    if (!adding_text && loaded['pages'] && loaded['text']){
        const pause = () => new Promise<void>(resolve => setTimeout(resolve, 0))
        adding_text = add_text(loaded['pages'] as Doc[], loaded['text'] as Record<string, string>, pause)
            .then(() => {
                with_text = true
            })
    }
    return name === 'text' && adding_text ? adding_text : Promise.resolve()
}

function load(name:string):Promise<unknown>{
    if (name in loaded){
        return Promise.resolve(loaded[name])  // E.g. from the cache while idle
    }
    return loading[name] ??= sources[name]!()
        .then(async data => {
            await loaded_data(name, data)
            return data
        })
        .catch(error => {
            delete loading[name]
            failed.add(name)
            throw error
        })
}

// Start downloading as soon as someone looks like they're about to search
// NOTE One at a time, smallest and most needed first, so none is slowed by sharing the connection
async function warm(after_each?:() => void){
    for (const name of enabled().filter(n => !failed.has(n))){
        const was_loaded = name in loaded
        const ok = await load(name).then(() => true, () => false)
        if (!was_loaded){
            after_each?.()
        }
        if (!ok){
            break  // Probably offline, so the rest would fail too
        }
    }
}


// RENDERING

// Results are rendered in batches as laying them out is what takes longest on phones
const BATCH = 12  // A little more than fits

let hits:Doc[] = []  // All results for the query
let shown:Result[] = []  // Those rendered so far
let active = -1
let rendering = 0
let frame:number|undefined
let last_query = ''
let pool:{key:string, q:string, docs:Doc[]} = {key: '', q: '', docs: []}  // Matches of last query

const current_path = () => decodeURI(location.pathname).replace(/\.html$/, '').replace(/(.)\/$/, '$1')

function option(r:Result, i:number, q:string):string{
    const {d, href} = r
    const desc = q ? line(r, q) : esc(d.desc ?? '')
    const here = d.href === current_path() ? `<span class="here">You're here</span>` : ''
    return `<li role="option" id="p-opt-${i}" aria-selected="false" data-i="${i}">`
        + `<a href="${esc(href)}" tabindex="-1"${d.source === 'book' ? ' target="_self"' : ''}>`
        + `<span class="pt">${mark(d.title, q)}${here}</span><span class="ps">${esc(d.section)}</span>`
        + (desc ? `<span class="pd">${desc}</span>` : '') + '</a></li>'
}

function render_menu(){
    hits = []
    shown = menu.map(d => ({d, href: d.href}))
    list.value!.innerHTML = shown.map((r, i) => option(r, i, '')).join('')
    list.value!.classList.add('menu')
    set_active(0)
}

function render_empty(message:string){
    hits = []
    shown = []
    list.value!.innerHTML = `<li class="empty">${message}</li>`
    set_active(-1)
}

async function render(){
    const ticket = ++rendering
    const raw = input.value!.value.trim()
    if (!raw){
        last_query = ''
        render_menu()
        return
    }
    const names = enabled()
    const pending = names.filter(n => !loaded[n] && !failed.has(n))

    if (!loaded['pages']){
        // Only say so if genuinely waiting (first search, slow connection)
        const slow = setTimeout(() => {
            if (ticket === rendering){
                render_empty("Searching…")
            }
        }, 100)
        try {
            await load('pages')
        } catch {
            if (ticket === rendering){
                render_empty("Search couldn't be loaded. Please check your connection.")
            }
            return
        } finally {
            clearTimeout(slow)
        }
        if (ticket !== rendering){
            return  // A newer search started meanwhile
        }
    }

    // Show what's ready, then again when the rest arrives
    const again = () => {
        if (ticket === rendering){
            render()
        }
    }
    if (pending.length){
        warm(again)
    } else if (!with_text){
        adding_text?.then(again)  // Text came from the cache before the rest
    }

    const ready = names.filter(n => loaded[n])
    const ready_key = ready.join() + with_text
    const q = words(raw)
    const keep = q === last_query ? shown[active]?.d : undefined  // Keep choice when re-rendering
    last_query = q
    // Only search the previous matches when typing on (and searching the same sources)
    const narrowing = pool.key === ready_key && narrows(pool.q, q)
    const found = search(q, narrowing ? pool.docs : ready.flatMap(docs_of))
    pool = {key: ready_key, q, docs: found.matched}
    hits = found.top
    shown = []
    list.value!.classList.remove('menu')
    if (hits.length){
        list.value!.innerHTML = ''
        const kept = keep ? hits.indexOf(keep) : -1
        more(Math.max(BATCH, kept + 1))
        set_active(kept >= 0 ? kept : 0)
    } else if (!with_text && (pending.includes('text') || adding_text)){
        render_empty("Searching…")  // Re-rendered when the text is ready
    } else {
        render_empty(`Nothing matches “${esc(raw)}”.`)
    }
}

// Render more of the results (if there are more)
function more(count = BATCH){
    const added = hits.slice(shown.length, shown.length + count).map(d => target(d, last_query))
    if (added.length){
        const html = added.map((r, i) => option(r, shown.length + i, last_query)).join('')
        shown.push(...added)
        list.value!.insertAdjacentHTML('beforeend', html)
    }
}

function on_scroll(){
    const el = list.value!
    if (shown.length < hits.length && el.scrollTop + el.clientHeight > el.scrollHeight - 200){
        more()
    }
}

function set_active(i:number, scroll = true){
    if (i >= shown.length - 1 && shown.length < hits.length){
        more()
    }
    list.value!.querySelector('[aria-selected="true"]')?.setAttribute('aria-selected', 'false')
    active = i
    const el = i >= 0 ? list.value!.querySelector(`#p-opt-${i}`) : null
    el?.setAttribute('aria-selected', 'true')
    input.value!.setAttribute('aria-activedescendant', el ? el.id : '')
    if (!el || !scroll){
        return
    }
    if (i === 0){
        list.value!.scrollTop = 0  // Avoids layout work on every key
    } else {
        const box = list.value!.getBoundingClientRect()
        const rect = el.getBoundingClientRect()
        if (rect.top < box.top || rect.bottom > box.bottom){
            el.scrollIntoView({block: 'nearest'})
        }
    }
}

// No debounce as searching takes milliseconds, just one render per frame
function on_input(){
    if (frame === undefined){
        frame = requestAnimationFrame(() => {
            frame = undefined
            render()
        })
    }
}

function on_move(event:MouseEvent){
    const li = (event.target as Element).closest<HTMLElement>('[role=option]')
    if (li && Number(li.dataset['i']) !== active){
        set_active(Number(li.dataset['i']), false)
    }
}

function on_scope(event:Event){
    book_on.value = (event.target as HTMLInputElement).checked
    try {
        localStorage.setItem('search-book', book_on.value ? '1' : '0')
    } catch {}
    warm()
    render()
    input.value!.focus()
}


// GOING TO A RESULT

function go(new_tab:boolean){
    const result = shown[active]
    if (!result){
        return
    }
    if (new_tab){
        window.open(result.href, '_blank')  // Text fragment is all that can reach a new tab
    } else {
        list.value!.querySelector<HTMLAnchorElement>(`#p-opt-${active} a`)!.click()
    }
}

async function on_click(event:MouseEvent){
    const a = (event.target as Element).closest('a')
    if (!a || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || event.button !== 0){
        return
    }
    const li = a.closest<HTMLElement>('[role=option]')!
    const result = shown[Number(li.dataset['i'])]
    if (!result){
        return
    }
    event.preventDefault()  // Also stops VitePress's router handling the link
    close()

    if (result.d.source === 'book'){
        // The book is a separate page, where the browser highlights the text fragment itself
        location.href = result.href
        return
    }

    const url = new URL(result.d.href, location.href)
    if (!result.words){
        // Title or heading match: the router scrolls to any heading (allowing for the nav bar)
        await router.go(url.pathname + url.hash)
        return
    }
    if (url.pathname !== current_path()){
        await router.go(url.pathname + url.hash)
        await nextTick()
        // Let the page settle (scrolling to its anchor, Bible references being linked etc.)
        await new Promise(resolve => setTimeout(resolve, 60))
    }
    show_here(result.words)
}

// Scroll to and highlight the words found
function show_here(text:string){
    const root = document.querySelector<HTMLElement>('main .vp-doc')
        ?? document.querySelector<HTMLElement>('#VPContent')
    const range = root ? find_on_page(text, root) : null
    if (!range){
        return
    }
    const box = range.getBoundingClientRect()
    window.scrollTo({top: box.top + window.scrollY - window.innerHeight / 3})
    if ('highlights' in CSS){
        CSS.highlights.set('found', new Highlight(range))  // Replaces any previous highlight
        const clear = () => {
            CSS.highlights.delete('found')
            removeEventListener('pointerdown', clear)
            removeEventListener('keydown', clear)
        }
        setTimeout(() => {
            addEventListener('pointerdown', clear)
            addEventListener('keydown', clear)
        }, 0)
    } else {
        getSelection()?.removeAllRanges()
        getSelection()?.addRange(range)
    }
}

// First visible occurrence of text, in any case and spacing, as a range across text nodes
function find_on_page(text:string, root:HTMLElement):Range|null{
    const nodes:Text[] = []
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {acceptNode: node => {
        const el = node.parentElement
        if (!el || el.closest('script, style, dialog, [hidden], .header-anchor')){
            return NodeFilter.FILTER_REJECT
        }
        return el.checkVisibility?.() === false ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
    }})
    while (walker.nextNode()){
        nodes.push(walker.currentNode as Text)
    }
    const all = nodes.map(n => n.data).join('')
    const pattern = text.trim().split(/\s+/).map(w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
        .join('[\\s\\u200b\\u2060]+')
    const m = new RegExp(pattern, 'i').exec(all)
    if (!m){
        return null
    }
    const range = document.createRange()
    const stop = m.index + m[0].length
    let offset = 0
    let started = false
    for (const n of nodes){
        const end = offset + n.data.length
        if (!started && m.index < end){
            range.setStart(n, m.index - offset)
            started = true
        }
        if (started && stop <= end){
            range.setEnd(n, stop - offset)
            break
        }
        offset = end
    }
    return range
}


// OPENING AND CLOSING

function open(){
    const el = dialog.value
    if (!el || el.open){
        return
    }
    document.querySelectorAll<HTMLDialogElement>('dialog[open]').forEach(d => d.close())
    input.value!.value = ''
    failed = new Set()
    el.show()
    is_open.value = true
    input.value!.focus()
    warm()
    render()
}

function close(){
    dialog.value?.close()
}

function on_input_key(event:KeyboardEvent){
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp'){
        event.preventDefault()
        if (shown.length){
            set_active((active + (event.key === 'ArrowDown' ? 1 : -1) + shown.length) % shown.length)
        }
    } else if (event.key === 'Enter'){
        event.preventDefault()
        const new_tab = event.ctrlKey || event.metaKey
        // Typed faster than a frame: bring results up to date first, else keep the current choice
        if (frame !== undefined){
            cancelAnimationFrame(frame)
            frame = undefined
            render().then(() => go(new_tab))
        } else {
            go(new_tab)
        }
    }
}

function on_dialog_key(event:KeyboardEvent){
    if (event.key === 'Escape'){
        event.preventDefault()
        close()
    }
}

// Close when focus moves elsewhere on the page (e.g. tabbing out), as the page isn't inert
function on_document_focus(event:FocusEvent){
    if (dialog.value?.open && !dialog.value.contains(event.target as Node)){
        close()
    }
}

// Don't leave focus in the hidden input (unless already reopened, as close fires a tick later)
function on_close(){
    const el = dialog.value
    if (el && !el.open){
        is_open.value = false
        if (el.contains(document.activeElement)){
            (document.activeElement as HTMLElement).blur()
        }
    }
}

function is_editing(event:KeyboardEvent){
    const el = event.target as HTMLElement
    return el.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(el.tagName)
}

function on_document_key(event:KeyboardEvent){
    if ((event.ctrlKey || event.metaKey) && !event.altKey && !event.shiftKey
            && event.key.toLowerCase() === 'k'){
        event.preventDefault()
        if (dialog.value?.open){
            close()
        } else {
            open()
        }
    } else if (event.key === '/' && !is_editing(event) && !dialog.value?.open){
        event.preventDefault()
        open()
    } else if (event.key === 'Control' || event.key === 'Meta'){
        warm()  // Probably on the way to K
    }
}


onMounted(() => {
    mounted.value = true
    mac.value = /Mac|iPhone|iPad/.test(navigator.platform)
    try {
        book_on.value = localStorage.getItem('search-book') !== '0'
    } catch {}
    document.addEventListener('keydown', on_document_key)
    document.addEventListener('focusin', on_document_focus)

    // Returning searchers: prepare the data from the browser's cache while idle (never downloads)
    const idle = window.requestIdleCallback ?? ((f:() => void) => setTimeout(f, 1000))
    idle(() => {
        for (const name of enabled()){
            if (!loading[name]){
                sources[name]!({cache: 'only-if-cached', mode: 'same-origin'})
                    .then(data => loaded_data(name, data))
                    .catch(() => {})
            }
        }
    })
})

onBeforeUnmount(() => {
    document.removeEventListener('keydown', on_document_key)
    document.removeEventListener('focusin', on_document_focus)
})

</script>


<style lang='sass' scoped>

